def find_fixed_point(update, init, tol=1e-10, max_iter=10000):
    current = init.copy()
    for step in range(max_iter):
        next_scores = update(current)
        if max(abs(next_scores[i] - current[i]) for i in range(len(current))) < tol:
            return next_scores, step + 1
        current = next_scores
    return current, max_iter

def detect_phase_transitions(thresholds, scores, epsilon):
    transitions = []
    for t_idx in range(len(thresholds)):
        perturbed = thresholds.copy()
        perturbed[t_idx] += epsilon
        for i, s in enumerate(scores):
            old_tier = sum(1 for t in thresholds if t <= s)
            new_tier = sum(1 for t in perturbed if t <= s)
            if old_tier != new_tier:
                transitions.append({'threshold': t_idx, 'individual': i, 'old': old_tier, 'new': new_tier})
    return transitions

def cantor_ifs_iterate(c=1/3, depth=8):
    intervals = [(0.0, 1.0)]
    for _ in range(depth):
        new = []
        for a, b in intervals:
            new.append((c*a, c*b))
            new.append((c*a + (1-c), c*b + (1-c)))
        intervals = new
    return intervals
